        <span class="rolling-number" aria-hidden="true"><Transition name="desk-number"><b :key="selected.length">{{ selected.length }}</b></Transition></span>
        <span class="sr-only" role="status">{{ selected.length }} / {{ items.length }} {{ c.selected }}</span>
