        <label v-for="(s,i) in items" v-show="expanded || i < 3" :key="s.id" class="desk-select-card" :class="{ picked: selected.includes(s.id), buried: !expanded && i > 0 }" :style="{ '--stack-index': Math.min(i,2), '--reveal-index': Math.min(i,6) }" :inert="(!expanded && i > 0) || busy || undefined">
          <input type="checkbox" :checked="selected.includes(s.id)" :disabled="busy" @keydown="keyboard = true" @pointerdown="keyboard = false" @change="select(s.id, $event)"/>
          <SubIcon :icon="s.icon" :name="s.name" :size="32"/><span class="select-identity"><strong>{{ s.name }}</strong><small>{{ s.remark || s.plan || s.next_renewal_date }}</small></span><span class="desk-amount">{{ formatAmount(s.amount) }}<small>{{ s.currency }}</small></span>
        </label>
      </div>
      <p v-if="items.length" class="desk-footnote">{{ layoutCopy.note }}</p>
    </section>
    <div v-if="selected.length && !success" class="desk-action-bar"><div><strong>{{ selected.length }}</strong><span>{{ c.selected }}</span></div><button class="btn" :disabled="busy" @click="openDialog(reviewDialog, $event)">{{ layoutCopy.review }}<span aria-hidden="true" v-html="icon('chevron')"></span></button></div>
    <dialog ref="filterDialog" class="desk-sheet" aria-labelledby="desk-filter-title"><div class="sheet-handle" aria-hidden="true"></div><div class="sheet-heading"><h2 id="desk-filter-title">{{ c.horizon }}</h2><button class="sheet-close" :aria-label="layoutCopy.close" @click="filterDialog.close()"><span aria-hidden="true" v-html="icon('x')"></span></button></div><InertiaWheel v-model="horizon" :options="[7,14,30,60,90,180,365]" :label="c.horizon" :unit="c.days" :decrease-label="accessCopy.less" :increase-label="accessCopy.more"/><p class="sheet-note">{{ layoutCopy.filterHint }}</p><button class="btn sheet-done" @click="filterDialog.close()">{{ layoutCopy.apply }}</button></dialog>
    <dialog ref="reviewDialog" class="desk-sheet" aria-labelledby="desk-review-title" @cancel="busy && $event.preventDefault()"><div class="sheet-handle" aria-hidden="true"></div><div class="sheet-heading"><h2 id="desk-review-title">{{ success ? c.saved : layoutCopy.review }}</h2><button class="sheet-close" :disabled="busy" :aria-label="layoutCopy.close" @click="reviewDialog.close()"><span aria-hidden="true" v-html="icon('x')"></span></button></div>
      <p class="sheet-note">{{ c.localHint }}</p><ul v-if="!success" class="desk-review-list"><li v-for="s in selectedRows" :key="s.id"><strong>{{ s.name }}</strong><span v-if="s.remark || s.plan">{{ s.remark || s.plan }}</span><span>{{ s.next_renewal_date }} · {{ formatAmount(s.amount) }} {{ s.currency }}</span></li></ul>
      <fieldset v-if="!success" :disabled="busy"><legend>{{ c.mode }}</legend><label :class="{ chosen: mode === 'today' }"><input v-model="mode" type="radio" value="today"/>{{ c.today }}</label><label :class="{ chosen: mode === 'due' }"><input v-model="mode" type="radio" value="due"/>{{ c.expiry }}</label></fieldset>
      <button class="desk-complete" :class="{ completed: success }" :disabled="busy || !selected.length || success" @click="complete"><span class="complete-fill" aria-hidden="true"></span><span v-if="!success" class="complete-label">{{ busy ? c.saving : c.complete }}</span><svg v-else class="complete-check" viewBox="0 0 32 32" aria-hidden="true"><path d="m8 16 5 5 11-12"/></svg><i v-for="n in success ? 8 : 0" :key="n" class="complete-particle" :style="{ '--angle': `${n * 45}deg` }" aria-hidden="true"></i><span v-if="success" class="sr-only">{{ c.saved }}</span></button><p role="status" class="desk-result">{{ message }}</p>
    </dialog>
  </div>
</template>
<script setup>
