  zh: { title:'续费工作台', hint:'查看近期到期，核对后记录续费。', selected:'已选', horizon:'查看未来', wheelHint:'上下滑动滚轮，松手选择天数。包含已过期订阅。', days:'天', timeline:'到期时间线', subscriptions:'待续费订阅', expand:'展开卡片', collapse:'收起卡片', empty:'这个时间范围内没有待续费订阅。', review:'核对并完成', localHint:'仅记录已经完成的续费，并更新到期日。不会执行扣款。', mode:'新的周期从何时开始', today:'从今天重新计算', expiry:'从原到期日继续计算', complete:'确认已续费', saving:'正在保存…', saved:'已记录续费', partial:'部分保存失败，请重试剩余项目。', failed:'保存失败，请重试。' },
  en: { title:'Renewal desk', hint:'Review upcoming renewals before recording payment.', selected:'Selected', horizon:'Look ahead', wheelHint:'Swipe the wheel and release to choose days. Includes overdue subscriptions.', days:'days', timeline:'Renewal timeline', subscriptions:'Subscriptions to renew', expand:'Expand cards', collapse:'Stack cards', empty:'No renewals in this period.', review:'Review and complete', localHint:'Records completed renewals and updates due dates. No payment is taken.', mode:'Start the new cycle', today:'From today', expiry:'From the previous due date', complete:'Confirm renewed', saving:'Saving…', saved:'Renewal recorded', partial:'Some items failed. Retry the remaining items.', failed:'Could not save. Please retry.' },
  ru: { title:'Продления', hint:'Проверьте подписки перед записью продления.', selected:'Выбрано', horizon:'Период', wheelHint:'Прокрутите и отпустите для выбора дней. Включая просроченные подписки.', days:'дн.', timeline:'Сроки продления', subscriptions:'Подписки для продления', expand:'Развернуть', collapse:'Сложить', empty:'В этом периоде нет продлений.', review:'Проверить и завершить', localHint:'Записывает выполненные продления и обновляет даты. Оплата не списывается.', mode:'Начало нового периода', today:'С сегодняшнего дня', expiry:'С прежней даты', complete:'Подтвердить продление', saving:'Сохранение…', saved:'Продление записано', partial:'Часть записей не сохранена. Повторите для оставшихся.', failed:'Не удалось сохранить. Повторите.' }
}
const c = computed(() => words[locale.value] || words.en)
