  zh: { eyebrow:'RENEWALS', title:'续费计划', due:'项待安排', timeline:'接下来到期', details:'详情', swipe:'上下滑动查看到期项目', choose:'选择已续费的订阅', expand:'查看全部', collapse:'收起', note:'选择后核对续费方式，再记录新的到期日。', review:'核对续费', close:'关闭', filterHint:'滚动或点按选择范围，包含已过期订阅。', apply:'使用这个范围' },
  en: { eyebrow:'RENEWALS', title:'Renewal plan', due:'renewals ahead', timeline:'Coming up', details:'Details', swipe:'Swipe to explore renewals', choose:'Select renewed subscriptions', expand:'View all', collapse:'Collapse', note:'Choose subscriptions, then review how the next cycle starts.', review:'Review renewals', close:'Close', filterHint:'Scroll or tap to choose a period. Includes overdue subscriptions.', apply:'Apply period' },
  ru: { eyebrow:'ПРОДЛЕНИЯ', title:'План продлений', due:'подписок к продлению', timeline:'Ближайшие сроки', details:'Подробнее', swipe:'Листайте сроки продления', choose:'Выберите продлённые подписки', expand:'Показать все', collapse:'Свернуть', note:'Выберите подписки и проверьте начало следующего периода.', review:'Проверить', close:'Закрыть', filterHint:'Прокрутите или нажмите для выбора периода. Включая просроченные.', apply:'Применить' }
}[locale.value] || { eyebrow:'RENEWALS', title:'Renewal plan', due:'renewals ahead', timeline:'Coming up', details:'Details', swipe:'Swipe to explore renewals', choose:'Select renewed subscriptions', expand:'View all', collapse:'Collapse', note:'Choose subscriptions, then review how the next cycle starts.', review:'Review renewals', close:'Close', filterHint:'Choose a period.', apply:'Apply period' }))
const filterDialog = ref(null), reviewDialog = ref(null)
function openDialog(dialog, event) { if (busy.value) return; keyboard.value = event?.detail === 0; dialog?.showModal() }
function formatAmount(value) { return Number(value || 0).toLocaleString(locale.value, { minimumFractionDigits:2, maximumFractionDigits:2 }) }
