function scrollRail() { clearTimeout(scrollTimer); scrollTimer = setTimeout(() => { const el = rail.value; if (!el) return; const cards = [...el.children]; active.value = cards.reduce((best,card,i) => Math.abs(card.offsetTop - el.scrollTop - 18) < Math.abs(cards[best].offsetTop - el.scrollTop - 18) ? i : best, 0) }, 110) }
