onBeforeUnmount(() => clearTimeout(scrollTimer))
onBeforeRouteLeave(() => {
  if (busy.value) return false
  const sheet = [filterDialog.value, reviewDialog.value].find(dialog => dialog?.open)
  if (sheet) { sheet.close(); return false }
  return true
